<?php require_once __DIR__.'/../config.php'; session_name(SESSION_NAME); session_set_cookie_params(['httponly'=>true,'samesite'=>'Lax','secure'=>!empty($_SERVER['HTTPS']),'path'=>'/']); if(session_status()!==PHP_SESSION_ACTIVE)session_start(); function db(){static $p;if($p)return $p;if(!is_dir(dirname(DB_PATH)))mkdir(dirname(DB_PATH),0750,true);$p=new PDO('sqlite:'.DB_PATH);$p->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$p->exec('PRAGMA foreign_keys=ON');return $p;} function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} function uid(){return $_SESSION['doctor_id']??0;} function auth(){if(!uid()){header('Location:/medical/login.php');exit;}} function csrf(){return $_SESSION['csrf']??($_SESSION['csrf']=bin2hex(random_bytes(32)));} function verify_csrf(){if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(419);exit('Sessão expirada.');}}